import json,re,sys,os,subprocess
R=sys.argv[1]; SS=R+'/system-spec'
st=json.load(open(SS+'/spec-state.json')); fr=json.load(open(SS+'/fetched-references.json'))['references']
reg=json.load(open(R+'/plugins/system-spec-harness/skills/ref-system-design-knowledge/references/doctrine-anchor-registry.json'))
topo=json.loads(subprocess.check_output(['python3',R+'/plugins/system-spec-harness/scripts/validate-knowledge-graph.py','--profile','knowledge','--input',R+'/plugins/system-spec-harness/skills/ref-system-design-knowledge/references/knowledge-catalog.json','--order']))
qa={q['id']:q for q in st['qa_log']}
concerns={}
for c in reg['concerns']:
    k=c.get('concern') or c.get('id') or c.get('name'); concerns[k]=c
print('concern keys sample', list(reg['concerns'][0].keys()))
res={}
PL=['web','mobile','tablet','desktop-windows','desktop-linux','desktop-macos']
for cat in [c['id'] for c in st['categories']]:
    t=open(f'{SS}/{cat}.md').read(); r={}
    fm=t.split('---\n')[1]
    keys=[l.split(':')[0] for l in fm.strip().splitlines()]
    r['fm_keys']=keys
    m=st['matrix'][cat]
    # aggregate
    conf_missing=[];oos_missing=[];verb_bad=[]
    sg=[]
    for p in PL:
        c=m[p]
        if c['state']=='確定':
            for ref in [c['qa_ref']]+c.get('qa_refs',[]):
                if f'`{ref}`' not in t: conf_missing.append(ref)
                q=qa[ref]
                body=t.split('## 確定内容 (質疑録)')[1].split('## To-Be')[0]
                if q['question'] not in body or q['answer'] not in body: verb_bad.append(ref)
            for g in c.get('serves_goals',[]):
                if g not in sg: sg.append(g)
        elif c['state']=='対象外':
            row=[l for l in t.splitlines() if l.startswith('|') and f'({p})' in l]
            reason=c.get('reason') or ('承認: '+c.get('approval_ref',''))
            if not row or '対象外' not in row[0] or reason.replace('\n','<br>').replace('|','\\|') not in row[0]: oos_missing.append(p)
            if c.get('approval_ref') and f'### 承認: `{c["approval_ref"]}`' not in t: oos_missing.append(p+':appr-section')
    r['conf_missing']=conf_missing; r['oos_missing']=oos_missing; r['verbatim_bad']=verb_bad
    fsg=re.search(r'serves_goals: \[(.*)\]',fm).group(1)
    r['serves_goals_fm']=fsg; r['serves_goals_expected']=', '.join(sg)
    # design knowledge
    dk=t.split('## 適用された設計知識')[1].split('## 最新ドキュメント出典')[0]
    cards=re.findall(r'出典カード: `ref-system-design-knowledge/references/([\w-]+)\.md`',dk)
    r['cards']=cards
    idx=[topo.index(c) for c in cards if c in topo]
    r['topo_ok']= idx==sorted(idx) and len(idx)==len(cards)
    secs=re.split(r'\n### ',dk)
    probgoal=[]
    for s in secs:
        if 'deep knowledge card' in s.splitlines()[0]:
            ok=('#### 解決する問題' in s and '#### goalへの寄与' in s)
            gsec=s.split('#### goalへの寄与')[1].strip() if '#### goalへの寄与' in s else ''
            probgoal.append(ok and len(gsec)>20)
    r['card_prob_goal']=probgoal
    r['adopt_section']='### 確定判断ごとの原則採否' in dk and dk.rfind('### 確定判断ごとの原則採否')>dk.rfind('deep knowledge card')
    adopt=dk.split('### 確定判断ごとの原則採否')[1] if r['adopt_section'] else ''
    # bind check: each confirmed cell qa's design_applications principle present
    miss=[]
    for p in PL:
        c=m[p]
        if c['state']!='確定': continue
        for ref in [c['qa_ref']]+c.get('qa_refs',[]):
            pass
        ref=c['qa_ref']; das=qa[ref].get('design_applications')
        if f'`{ref}`' not in adopt: miss.append(ref+':ref')
        if das:
            for d in das:
                for fld in ('principle','rationale'):
                    if d[fld] not in adopt: miss.append(f'{ref}:{fld}')
                if f"`{d['applicability']}`" not in adopt: miss.append(ref+':applic')
                for tr in d.get('tradeoffs',[]):
                    if tr not in adopt: miss.append(ref+':tradeoff')
        else:
            if 'unrecorded' not in adopt: miss.append(ref+':unrecorded')
    if not any(m[p]['state']=='確定' for p in PL):
        r['adopt_no_confirmed_text']=adopt.strip()[:200]
    r['adopt_bind_miss']=miss
    # doctrine
    dm=reg['category_concern_map'].get(cat)
    ds=t.split('## 上流指針 (doctrine anchors)')[1].split('## 確定内容')[0]
    dmiss=[]
    for cc in dm or []:
        auth=[x for x in reg['concerns'] if cc in json.dumps(x,ensure_ascii=False)][0]['authority']
        row=[l for l in ds.splitlines() if l.startswith(f'| {cc} |')]
        if not row or auth not in row[0]: dmiss.append(cc)
    r['doctrine_miss']=dmiss if dm else 'NOT_IN_MAP'
    # citations
    cs=t.split('## 最新ドキュメント出典')[1]
    exp=[x for x in fr if any(tg['target_id']==x['target_id'] and (tg['category']==cat or cat in tg.get('also_categories',[])) for tg in st['targets'])]
    cmiss=[]
    for x in exp:
        row=[l for l in cs.splitlines() if l.startswith(f"| {x['target_id']} |")]
        if not row or x['source_url'] not in row[0] or (x.get('version') or x.get('last_updated')) not in row[0] or x['official_host'] not in row[0] or x['latest_checked_at'] not in row[0]: cmiss.append(x['target_id'])
    rows=[l for l in cs.splitlines() if l.startswith('| ') and not l.startswith('| 対象')]
    r['cit_expected']=[x['target_id'] for x in exp]; r['cit_rows']=len(rows); r['cit_miss']=cmiss
    res[cat]=r
print(json.dumps(res,ensure_ascii=False,indent=1))
